CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password_hash text, role text NOT NULL CHECK(role IN ('admin','sdr')), availability text NOT NULL DEFAULT 'available' CHECK(availability IN ('available','unavailable','leave')), active boolean NOT NULL DEFAULT true, rotation_enabled boolean NOT NULL DEFAULT true, rotation_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE pipeline_stages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, position integer NOT NULL UNIQUE, kind text NOT NULL DEFAULT 'open' CHECK(kind IN ('open','won','lost')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE round_robin_state (id integer PRIMARY KEY CHECK(id=1), last_order bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO round_robin_state(id) VALUES(1);
CREATE TABLE settings (id integer PRIMARY KEY CHECK(id=1), company text NOT NULL DEFAULT 'NextDim', sla_minutes integer NOT NULL DEFAULT 15 CHECK(sla_minutes BETWEEN 1 AND 1440), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings(id) VALUES(1);
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email text, instagram text, company text, job_title text, city text, state text, owner_id uuid REFERENCES users(id), stage_id uuid NOT NULL REFERENCES pipeline_stages(id), source text NOT NULL, campaign text, ad_set text, ad text, utm_source text, utm_medium text, utm_campaign text, utm_content text, temperature text NOT NULL DEFAULT 'unclassified' CHECK(temperature IN ('hot','warm','cold','unclassified')), potential_value numeric(14,2) NOT NULL DEFAULT 0 CHECK(potential_value>=0), notes text, first_contact_at timestamptz, last_contact_at timestamptz, score integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE UNIQUE INDEX leads_phone_unique ON leads(phone) WHERE phone IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX leads_email_unique ON leads(email) WHERE email IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX leads_instagram_unique ON leads(instagram) WHERE instagram IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX leads_owner_stage ON leads(owner_id,stage_id) WHERE deleted_at IS NULL;
CREATE INDEX leads_created ON leads(created_at);
CREATE TABLE activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), actor_id uuid REFERENCES users(id), type text NOT NULL, description text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX activities_timeline ON activities(lead_id,created_at DESC);
CREATE TABLE lead_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), previous_owner_id uuid REFERENCES users(id), owner_id uuid REFERENCES users(id), actor_id uuid REFERENCES users(id), automatic boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_stage_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), previous_stage_id uuid REFERENCES pipeline_stages(id), stage_id uuid NOT NULL REFERENCES pipeline_stages(id), actor_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), source text NOT NULL, campaign text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_tags (lead_id uuid REFERENCES leads(id), tag_id uuid REFERENCES tags(id), PRIMARY KEY(lead_id,tag_id));
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, lead_id uuid REFERENCES leads(id), owner_id uuid NOT NULL REFERENCES users(id), due_at timestamptz NOT NULL, priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tasks_due ON tasks(owner_id,due_at) WHERE completed_at IS NULL;
CREATE TABLE followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), owner_id uuid NOT NULL REFERENCES users(id), due_at timestamptz NOT NULL, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX followups_due ON followups(owner_id,due_at) WHERE completed_at IS NULL;
CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid UNIQUE NOT NULL REFERENCES leads(id), owner_id uuid REFERENCES users(id), amount numeric(14,2) NOT NULL CHECK(amount>0), service text NOT NULL, closed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE loss_reasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid UNIQUE NOT NULL REFERENCES leads(id), reason text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), lead_id uuid REFERENCES leads(id), message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'disconnected', last_sync_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id), channel text NOT NULL CHECK(channel IN ('whatsapp','instagram')), unread boolean NOT NULL DEFAULT false, awaiting_reply boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), external_id text UNIQUE, body text NOT NULL, direction text NOT NULL CHECK(direction IN ('inbound','outbound')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, record_id uuid, previous jsonb, next jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text NOT NULL, bucket bigint NOT NULL, count integer NOT NULL, PRIMARY KEY(key,bucket));
CREATE TABLE webhook_receipts (key text PRIMARY KEY, payload_hash text NOT NULL, lead_id uuid REFERENCES leads(id), created_at timestamptz NOT NULL DEFAULT now());
